//! Units, their scale/offset and the runtime unit registry.
//!
//! A unit converts a value into the canonical unit of its dimension with
//! `canonical = value * scale + offset`. The scale models prefixes and
//! non-SI sizes, the offset models affine scales such as °C and °F.
//!
//! The registry is built once from the table generated by `build.rs` and then
//! shared: lookups are a binary search over the sorted symbols, with a
//! prefixed fallback (`Gs`, `mm`) and a "did you mean" suggestion.

use std::fmt::{self, Display, Formatter};
use std::sync::OnceLock;

use crate::dimension::Dimension;
use crate::error::{UnitError, UnitResult};
use crate::generated::{PREFIX_TABLE, UNIT_TABLE};
use crate::util;

/// One row of the generated unit table.
pub type UnitSeed = (&'static str, [i8; 7], f64, f64);

/// One row of the generated prefix table.
pub type PrefixSeed = (&'static str, i32);

/// A unit of measure.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Unit {
    symbol: &'static str,
    dimension: Dimension,
    scale: f64,
    offset: f64,
}

impl Unit {
    /// Builds a unit from its symbol, dimension and affine transform.
    pub const fn new(symbol: &'static str, dimension: Dimension, scale: f64, offset: f64) -> Self {
        Self {
            symbol,
            dimension,
            scale,
            offset,
        }
    }

    /// The dimensionless ratio `1`.
    pub const fn ratio() -> Self {
        Self::new("1", Dimension::NONE, 1.0, 0.0)
    }

    /// The symbol as written in configuration files.
    pub const fn symbol(&self) -> &'static str {
        self.symbol
    }

    /// The dimension this unit measures.
    pub const fn dimension(&self) -> Dimension {
        self.dimension
    }

    /// Multiplicative factor towards the canonical unit.
    pub const fn scale(&self) -> f64 {
        self.scale
    }

    /// Additive term towards the canonical unit.
    pub const fn offset(&self) -> f64 {
        self.offset
    }

    /// Whether the unit needs an offset, as °C and °F do.
    pub fn is_affine(&self) -> bool {
        self.offset != 0.0
    }

    /// Whether the transform is usable at all.
    pub fn is_finite(&self) -> bool {
        self.scale.is_finite() && self.offset.is_finite() && self.scale != 0.0
    }

    /// Whether two units measure the same dimension.
    pub fn compatible_with(&self, other: &Unit) -> bool {
        self.dimension == other.dimension
    }

    /// Converts a value of this unit into the canonical unit.
    pub fn to_canonical(&self, value: f64) -> f64 {
        value * self.scale + self.offset
    }

    /// Converts a canonical value into this unit.
    pub fn from_canonical(&self, canonical: f64) -> f64 {
        (canonical - self.offset) / self.scale
    }

    /// Converts `value` from this unit into `target`.
    ///
    /// # Errors
    ///
    /// Returns [`UnitError::DimensionMismatch`] when the dimensions differ.
    pub fn convert(&self, value: f64, target: &Unit) -> UnitResult<f64> {
        if !self.compatible_with(target) {
            return Err(UnitError::DimensionMismatch {
                expected: self.dimension.describe(),
                found: target.dimension.describe(),
            });
        }
        Ok(target.from_canonical(self.to_canonical(value)))
    }

    /// Returns a copy of this unit with its scale multiplied by `factor`.
    ///
    /// The symbol is kept, because the result usually represents a prefixed
    /// spelling of the same unit (`k` + `Pa`).
    ///
    /// # Errors
    ///
    /// Returns [`UnitError::OffsetUnit`] for affine units, where an extra
    /// factor would be ambiguous.
    pub fn scaled(&self, factor: f64) -> UnitResult<Unit> {
        if self.is_affine() {
            return Err(UnitError::OffsetUnit {
                symbol: self.symbol.to_string(),
            });
        }
        if !factor.is_finite() || factor == 0.0 {
            return Err(UnitError::NonFinite {
                input: factor.to_string(),
            });
        }
        Ok(Self {
            scale: self.scale * factor,
            ..*self
        })
    }

    /// The affine transform as text, used by `describe`.
    pub fn formula(&self) -> String {
        match self.offset {
            0.0 => format!("canonical = value * {}", util::format_float(self.scale)),
            offset => format!(
                "canonical = value * {} + {}",
                util::format_float(self.scale),
                util::format_float(offset)
            ),
        }
    }
}

impl Display for Unit {
    fn fmt(&self, formatter: &mut Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.symbol)
    }
}

/// A sorted collection of units.
#[derive(Debug, Clone)]
pub struct UnitRegistry {
    units: Vec<Unit>,
}

impl UnitRegistry {
    /// Builds the registry from the table generated by `build.rs`.
    pub fn builtin() -> Self {
        let units: Vec<Unit> = UNIT_TABLE
            .iter()
            .map(|(symbol, exponents, scale, offset)| {
                Unit::new(
                    symbol,
                    Dimension::from_exponents(*exponents),
                    *scale,
                    *offset,
                )
            })
            .collect();
        debug_assert_eq!(
            units.len(),
            crate::generated::GENERATED_UNIT_COUNT,
            "the generated unit table changed size"
        );
        Self { units }
    }

    /// Builds a registry from arbitrary units, sorting them by symbol.
    pub fn from_units(mut units: Vec<Unit>) -> Self {
        units.sort_by(|left, right| left.symbol().cmp(right.symbol()));
        Self { units }
    }

    /// Exact symbol lookup.
    pub fn lookup(&self, symbol: &str) -> Option<Unit> {
        let needle = symbol.trim();
        self.units
            .binary_search_by(|unit| unit.symbol().cmp(needle))
            .ok()
            .map(|index| self.units[index])
    }

    /// Resolves a symbol, falling back to prefixed spellings.
    ///
    /// # Errors
    ///
    /// Returns [`UnitError::UnknownUnit`] with a suggestion when nothing
    /// matches, and [`UnitError::MissingUnit`] for empty input.
    pub fn resolve(&self, symbol: &str) -> UnitResult<Unit> {
        let needle = symbol.trim();
        if needle.is_empty() {
            return Err(UnitError::MissingUnit {
                input: symbol.to_string(),
            });
        }
        if let Some(unit) = self.lookup(needle) {
            return Ok(unit);
        }
        if let Some(unit) = self.resolve_prefixed(needle) {
            return Ok(unit);
        }
        Err(UnitError::UnknownUnit {
            symbol: needle.to_string(),
            suggestion: self.suggest(needle).map(str::to_string),
        })
    }

    fn resolve_prefixed(&self, symbol: &str) -> Option<Unit> {
        let mut best: Option<(usize, Unit)> = None;
        for (prefix, power) in PREFIX_TABLE {
            if !symbol.starts_with(prefix) {
                continue;
            }
            let remainder = &symbol[prefix.len()..];
            if remainder.is_empty() {
                continue;
            }
            let Some(base) = self.lookup(remainder) else {
                continue;
            };
            if base.is_affine() {
                continue;
            }
            let factor = 10f64.powi(*power);
            let Ok(scaled) = base.scaled(factor) else {
                continue;
            };
            if best.is_none_or(|(length, _)| prefix.len() > length) {
                best = Some((prefix.len(), scaled));
            }
        }
        best.map(|(_, unit)| unit)
    }

    /// The closest known symbol, if any is close enough to be worth showing.
    pub fn suggest(&self, symbol: &str) -> Option<&'static str> {
        util::closest(symbol, self.units.iter().map(|unit| unit.symbol()), 3)
    }

    /// Iterates over every unit in symbol order.
    pub fn iter(&self) -> impl Iterator<Item = &Unit> {
        self.units.iter()
    }

    /// Number of registered units.
    pub fn len(&self) -> usize {
        self.units.len()
    }

    /// Whether the registry is empty.
    pub fn is_empty(&self) -> bool {
        self.units.is_empty()
    }

    /// Every symbol, in registry order.
    pub fn symbols(&self) -> Vec<&'static str> {
        self.units.iter().map(|unit| unit.symbol()).collect()
    }

    /// Every unit measuring `dimension`.
    pub fn with_dimension(&self, dimension: Dimension) -> Vec<Unit> {
        self.units
            .iter()
            .copied()
            .filter(|unit| unit.dimension() == dimension)
            .collect()
    }
}

static REGISTRY: OnceLock<UnitRegistry> = OnceLock::new();

/// The process wide registry built from the generated table.
pub fn registry() -> &'static UnitRegistry {
    REGISTRY.get_or_init(UnitRegistry::builtin)
}

/// Looks up a unit symbol in the process wide registry.
pub fn lookup(symbol: &str) -> Option<Unit> {
    registry().lookup(symbol)
}

/// Resolves a unit symbol in the process wide registry.
///
/// # Errors
///
/// See [`UnitRegistry::resolve`].
pub fn resolve(symbol: &str) -> UnitResult<Unit> {
    registry().resolve(symbol)
}

/// Every registered symbol.
pub fn symbols() -> Vec<&'static str> {
    registry().symbols()
}

/// Every unit measuring `dimension`.
pub fn units_with_dimension(dimension: Dimension) -> Vec<Unit> {
    registry().with_dimension(dimension)
}

#[cfg(test)]
mod tests {
    use super::{Unit, UnitRegistry, lookup, registry, resolve, units_with_dimension};
    use crate::dimension::Dimension;
    use crate::error::UnitError;
    use crate::generated::{
        GENERATED_PREFIX_COUNT, GENERATED_UNIT_COUNT, PREFIX_TABLE, UNIT_TABLE,
    };

    #[test]
    fn generated_table_is_sorted_and_unique() {
        assert_eq!(UNIT_TABLE.len(), GENERATED_UNIT_COUNT);
        assert!(registry().len() >= 40, "table should stay realistic");
        for pair in UNIT_TABLE.windows(2) {
            assert!(
                pair[0].0 < pair[1].0,
                "{} must come before {}",
                pair[0].0,
                pair[1].0
            );
        }
        assert_eq!(PREFIX_TABLE.len(), GENERATED_PREFIX_COUNT);
    }

    #[test]
    fn registry_finds_the_base_units() {
        let metre = lookup("m").expect("metre is registered");
        assert_eq!(metre.dimension(), Dimension::LENGTH);
        assert_eq!(metre.scale(), 1.0);
        assert_eq!(metre.offset(), 0.0);
        assert!(!metre.is_affine());
        assert!(metre.is_finite());
        assert_eq!(metre.to_string(), "m");
    }

    #[test]
    fn registry_resolves_scales_and_offsets() {
        let kilopascal = lookup("kPa").expect("kPa is registered");
        assert_eq!(kilopascal.scale(), 1000.0);
        assert_eq!(kilopascal.to_canonical(1.5), 1500.0);
        let celsius = lookup("degC").expect("degC is registered");
        assert!(celsius.is_affine());
        assert_eq!(celsius.to_canonical(0.0), 273.15);
        assert_eq!(celsius.from_canonical(273.15), 0.0);
    }

    #[test]
    fn prefixed_lookups_fall_back_to_the_prefix_table() {
        let gigasecond = resolve("Gs").expect("G + s resolves");
        assert_eq!(gigasecond.dimension(), Dimension::TIME);
        assert_eq!(gigasecond.scale(), 1.0e9);
        let millimetre = resolve("mm").expect("mm is an exact symbol");
        assert_eq!(millimetre.scale(), 0.001);
        let unknown = resolve("degCx").unwrap_err();
        assert!(matches!(unknown, UnitError::UnknownUnit { .. }));
    }

    #[test]
    fn unknown_symbols_get_a_suggestion() {
        let error = resolve("kPaa").unwrap_err();
        match error {
            UnitError::UnknownUnit { symbol, suggestion } => {
                assert_eq!(symbol, "kPaa");
                assert_eq!(suggestion.as_deref(), Some("kPa"));
            }
            other => panic!("unexpected error: {other}"),
        }
        assert_eq!(registry().suggest("zzzzzz"), None);
    }

    #[test]
    fn empty_symbols_report_a_missing_unit() {
        assert_eq!(
            resolve("   "),
            Err(UnitError::MissingUnit {
                input: "   ".to_string()
            })
        );
    }

    #[test]
    fn conversion_checks_dimensions() {
        let bar = lookup("bar").expect("bar is registered");
        let pascal = lookup("Pa").expect("Pa is registered");
        assert_eq!(bar.convert(1.0, &pascal).unwrap(), 100_000.0);
        let second = lookup("s").expect("s is registered");
        assert_eq!(
            bar.convert(1.0, &second),
            Err(UnitError::DimensionMismatch {
                expected: "LEN-1 MASS1 TIME-2".to_string(),
                found: "TIME1".to_string(),
            })
        );
    }

    #[test]
    fn scaling_rejects_affine_units() {
        let celsius = lookup("degC").expect("degC is registered");
        assert_eq!(
            celsius.scaled(1000.0),
            Err(UnitError::OffsetUnit {
                symbol: "degC".to_string()
            })
        );
        let metre = lookup("m").expect("m is registered");
        assert_eq!(metre.scaled(1000.0).unwrap().scale(), 1000.0);
        assert_eq!(
            metre.scaled(0.0),
            Err(UnitError::NonFinite {
                input: "0".to_string()
            })
        );
    }

    #[test]
    fn units_can_be_filtered_by_dimension() {
        let pressures = units_with_dimension(Dimension::PRESSURE);
        let symbols: Vec<&str> = pressures.iter().map(|unit| unit.symbol()).collect();
        assert!(symbols.contains(&"Pa"));
        assert!(symbols.contains(&"psi"));
        assert!(!symbols.contains(&"s"));
        assert_eq!(
            pressures.iter().filter(|unit| unit.scale() == 1.0).count(),
            1
        );
    }

    #[test]
    fn custom_registries_are_sorted() {
        let registry = UnitRegistry::from_units(vec![
            Unit::new("zz", Dimension::LENGTH, 2.0, 0.0),
            Unit::new("aa", Dimension::LENGTH, 1.0, 0.0),
        ]);
        assert_eq!(registry.symbols(), vec!["aa", "zz"]);
        assert_eq!(registry.len(), 2);
        assert!(!registry.is_empty());
        assert_eq!(registry.iter().count(), 2);
        assert_eq!(Unit::ratio().dimension(), Dimension::NONE);
        assert_eq!(
            registry.lookup("aa").expect("present").formula(),
            "canonical = value * 1"
        );
    }
}
